 let pendingEncrypted=null;let active=true,notice='',busy=false,cachedData=null,cachedView=null;const feedback={receipt:null,cash:null,history:null},drafts={receipt:null,cash:null};const cashDrafts=new Map(),paymentOpenByReceipt=new Map(),breakdownOpenByReceipt=new Map();let accountSearch='',choosingAccount=false;let historyExpanded=false,historyTouched=false,breakdownHelpOpen=false;let receiptHistoryTarget='',confirmingReset=false,accountFilter=initialAccountRef,selectedReceipt=initialReceiptId||'',selectedAccount='',receiptSearch='',pendingPanel=['receipt','cash','history'].includes(initialPanel)?initialPanel:null;
