 const receiptOptions=entries=>entries.map(({receipt:r,financial:f})=>'<option value="'+escape(r.receiptId)+'">'+escape((receiptDay(r)||'')+' · '+accountLabel(r.accountRef)+' · '+(r.merchant||r.service||'Receipt')+(f.needsAdjustmentReview?' · refund / adjustment review':f.incomplete?' · savings missing':''))+'</option>').join('');
 function updateReceiptOptions(){const field=host.querySelector('#financeReceipt'),previous=field.value;field.innerHTML=receiptOptions(matchingReceipts());if([...field.options].some(o=>o.value===previous))field.value=previous;selectedReceipt=field.value;host.querySelector('[data-finance-form="receipt"] button[type="submit"]').disabled=!field.value;if(previous!==field.value){feedback.receipt=null;drafts.receipt=null;showFeedback('receipt');if(field.value)receiptSelected();else{clearReceiptPreview();for(const input of host.querySelectorAll('[data-finance-form="receipt"] input[name]'))input.value='';updateBreakdown();}}updateHistoryButtons('receipt',field.value);}
