 function updateBreakdown(){const fields=financialCategories.map(k=>host.querySelector('#finance-'+k)),values=fields.filter(e=>e&&e.value!=='').map(e=>Number(e.value));const total=values.reduce((n,v)=>n+Math.round(v*100),0)/100;const entered=host.querySelector('#financeTotal')?.value,target=entered===''?null:Number(entered);const result=host.querySelector('[data-finance-breakdown-total]'),hint=host.querySelector('[data-finance-breakdown-check]');if(!result||!hint)return;result.textContent=values.length?money(total):'Not entered';hint.dataset.state=!values.length?'empty':target==null?'incomplete':Math.abs(total-target)<.011?'match':'mismatch';hint.textContent=!values.length?'Leave blank if unavailable.':target==null?'Enter total savings above.':Math.abs(total-target)<.011?'Matches total savings.':total>target?'Breakdown exceeds total savings by '+money(total-target)+'.':money(target-total)+' still to allocate.';}
